-- 커리큘럼 시드: 학생 기록을 수정하지 않음. 300 + 400 + 500 어휘 항목.
BEGIN;
ON CONFLICT(id) DO UPDATE SET name_ko=excluded.name_ko,grade_min=excluded.grade_min,grade_max=excluded.grade_max,expected_words=excluded.expected_words,sort_order=excluded.sort_order,status=excluded.status;
ON CONFLICT(id) DO UPDATE SET level_id=excluded.level_id,unit_no=excluded.unit_no,title_en=excluded.title_en,title_ko=excluded.title_ko,icon=excluded.icon,status=excluded.status;
ON CONFLICT(id) DO UPDATE SET content_key=excluded.content_key,stage=excluded.stage,topic=excluded.topic,en=excluded.en,ko=excluded.ko,example=excluded.example,translation=excluded.translation,status=excluded.status,updated_at=now();
ON CONFLICT(legacy_id) DO UPDATE SET word_id=excluded.word_id;
UPDATE ojv.content_versions SET snapshot=ojv.content_snapshot() WHERE version='2026.11.07.1';
COMMIT;
